"""Verify fix for django__django-7530: makemigrations allow_migrate() consistency
check must pass each app's OWN models, not every model in the project.

Old code:  apps.get_models(app_label)  -> get_models() has signature
                                       (include_auto_created=False, include_swapped=False),
                                       so a string app_label was bound to include_auto_created
                                       and ALL project models were returned for every app.
New code:  apps.get_app_config(app_label).get_models() -> that app's models only.

We assert the router receives (app_label, model_name) pairs where model_name
actually belongs to app_label, and that each project model is checked against
its own app (never cross-app).
"""


class App:
    def __init__(self, label, models):
        self.label = label
        self._models = models

    def get_models(self):
        return list(self._models)


class FakeApps:
    def __init__(self, configs):
        self._configs = {c.label: c for c in configs}
        self._all_models = [m for c in configs for m in c._models]

    @property
    def app_configs(self):
        return self._configs

    def get_app_config(self, label):
        return self._configs[label]

    # Old buggy call: returns EVERY model for any app_label (get_models ignores it).
    def get_models(self, app_label=None):
        return list(self._all_models)


class Model:
    def __init__(self, app_label, name):
        self._meta = type('Meta', (), {
            'object_name': name,
            'model_name': name.lower(),
        })()
        self.app_label = app_label


auth = App('auth', [Model('auth', 'User'), Model('auth', 'Group')])
blog = App('blog', [Model('blog', 'Post')])
apps = FakeApps([auth, blog])

call_log = []
router = type('Router', (), {'allow_migrate': staticmethod(
    lambda alias, app_label, model_name=None:
        call_log.append((app_label, model_name)) or True)})()

consistency_check_labels = set('auth blog'.split())
# Simulate the makemigrations expression with the FIXED code.
any(
    router.allow_migrate('default', app_label, model_name=model._meta.object_name)
    for app_label in consistency_check_labels
    for model in apps.get_app_config(app_label).get_models()
)

# Every (app_label, model_name) pair must be internally consistent.
OWN = {'auth': {'User', 'Group'}, 'blog': {'Post'}}
assert call_log, "router must have been consulted"
for app_label, model_name in call_log:
    assert model_name in OWN[app_label], (
        "MISMATCH: %s does not belong to app %s" % (model_name, app_label))

