New code:  apps.get_app_config(app_label).get_models() -> that app's models only.

We record every (app_label, model_name) pair consulted and assert each is
internally consistent (model belongs to its app_label). Short-circuiting any()
is avoided so we inspect the full pairing, matching the ticket's concern.
"""


class App:
    def __init__(self, label, models):
        self.label = label
        self._models = models

    def get_models(self):
        return list(self._models)


class FakeApps:
    def __init__(self, configs):
        self._configs = {c.label: c for c in configs}
        self._all_models = [m for c in configs for m in c._models]

    def get_app_config(self, label):
        return self._configs[label]

    # Old buggy call: returns EVERY model for any app_label (get_models ignores it).
    def get_models(self, app_label=None):
        return list(self._all_models)


class Model:
    def __init__(self, app_label, name):
        self._meta = type('Meta', (), {
            'object_name': name,
            'model_name': name.lower(),
        })()
        self.app_label = app_label


auth = App('auth', [Model('auth', 'User'), Model('auth', 'Group')])
blog = App('blog', [Model('blog', 'Post')])
apps = FakeApps([auth, blog])
consistency_check_labels = ['auth', 'blog']
OWN = {'auth': {'User', 'Group'}, 'blog': {'Post'}}
ALL_MODELS = ['User', 'Group', 'Post']


def new_pairs():
    return [
        (app_label, m._meta.object_name)
        for app_label in consistency_check_labels
        for m in apps.get_app_config(app_label).get_models()
    ]


def old_pairs():
    return [
        (app_label, m._meta.object_name)
        for app_label in consistency_check_labels
        for m in apps.get_models(app_label)
    ]


new = new_pairs()
for a, m in new:
    assert m in OWN[a], "%s not in app %s" % (m, a)
print("NEW: pairs =", sorted(new), "-> all internally consistent")

old = old_pairs()
cross = [(a, m) for a, m in old if m not in OWN[a]]
assert cross, "old code must exhibit cross-app mismatches"
print("OLD: pair count =", len(old), "cross-app mismatches =", cross)

# Real router signatures aside, the pairing is what the ticket is about.
# New code also consults allow_migrate fewer times (no redundant all-models loop).
assert len(new) == len(ALL_MODELS) and len(old) == len(ALL_MODELS) * 2
print("NEW consults allow_migrate %d times (once per project model); "
      "OLD consulted it %d times (every model per app)." % (len(new), len(old)))
