class LooseVersion(_LV):
    """
    Minimal backport of distutils.version.LooseVersion (removed in Python
    3.12) -- only what Django's own get_version_tuple() needs.
    """
    def __init__(self, vstring=None):
        if vstring:
            self.parse(vstring)

    def parse(self, vstring):
        import re
        component_re = re.compile(r'(\d+ | [a-z]+ | \.)', re.VERBOSE)
        self.vstring = vstring
        components = [x for x in component_re.split(vstring) if x and x != '.']
        for i, obj in enumerate(components):
            try:
                components[i] = int(obj)
            except ValueError:
                pass
        self.version = components

    def __str__(self):
        return self.vstring

    def __repr__(self):
        return "LooseVersion ('%s')" % str(self)

    def __eq__(self, other):
        if isinstance(other, str):
            other = LooseVersion(other)
        return self.version == other.version

    def __lt__(self, other):
        if isinstance(other, str):
            other = LooseVersion(other)
        return self.version < other.version

