"""Minimal local stand-in for the `py` package, subpath `py.path`.

Only the pieces _pytest imports at module level are provided so the test
runner can boot in this offline environment (no `py` wheel available).
"""
import os

__version__ = "1.10.0"


class _LocalPath:
    sep = os.path.sep

    def __init__(self, path):
        self.strpath = os.fspath(path)

    def __fspath__(self):
        return self.strpath

    def __str__(self):
        return self.strpath

    def __repr__(self):
        return "local(%r)" % self.strpath

    def __eq__(self, other):
        return isinstance(other, _LocalPath) and self.strpath == other.strpath

    def __hash__(self):
        return hash(self.strpath)


def local(path):
    return _LocalPath(path)


def realpath(path):
    return os.path.realpath(os.fspath(path))


class _PathModule:
    local = staticmethod(local)
    realpath = staticmethod(realpath)


class path:  # noqa: N801 - mirrors py's class-style namespace
    local = local
    realpath = realpath
    common = os.path.commonprefix

