"""Tiny stand-in for the `pluggy` package, enough to boot this pytest checkout.

Supports: HookspecMarker/HookimplMarker, PluginManager with hook
registration, call_historic/call_extra, hookwrapper + tryfirst/trylast
ordering, hook relays. Not a general-purpose pluggy.
"""
import inspect
import warnings

__version__ = "0.13.1"
_SPECS = {}


class _Marker:
    def __init__(self, project_name, *, spec=False):
        self.project_name = project_name
        self.spec = spec

    def __call__(self, function=None, **kwargs):
        def setattr_hookimpl(func):
            func.__dict__.setdefault(self.project_name + "_impl", {}).update(kwargs)
            if self.spec:
                func.__dict__.setdefault(self.project_name + "_spec", {}).update(kwargs)
            return func

        if function is not None:
            return setattr_hookimpl(function)
        return setattr_hookimpl


class HookspecMarker(_Marker):
    def __init__(self, project_name):
        super().__init__(project_name, spec=True)


class HookimplMarker(_Marker):
    def __init__(self, project_name):
        super().__init__(project_name, spec=False)


class HookCallError(Exception):
    pass


class _HookImpl:
    __slots__ = ("plugin", "func", "name", "wrapper", "tryfirst", "trylast")

    def __init__(self, plugin, name, func, opts):
        self.plugin = plugin
        self.name = name
        self.func = func
        self.wrapper = opts.pop("hookwrapper", False)
        self.tryfirst = opts.pop("tryfirst", False)
        self.trylast = opts.pop("trylast", False)

    def __repr__(self):
        return "<HookImpl {}>".format(self.name)


class _Caller:
    def __init__(self, name, impls):
        self.name = name
        self.impls = impls
        self._historic = []

    def __call__(self, **kwargs):
        return self.call_extra(kwargs, {}) if False else self._call(kwargs, extra=None)

    def call_extra(self, methods, extra):
        self._call(methods, extra=extra)

    def call_historic(self, kwargs=None, result_callback=None, **extra):
        self._historic.append((kwargs or {}, extra or None))
        if result_callback is not None:
            result_callback(None)

    def call_extra_historic(self, methods, extra):
        self._historic.append((methods, extra))

    def _call(self, kwargs, extra):
        methods = kwargs
        if extra is not None:
            methods = dict(methods)
            methods.update(extra)
        results = []
        for hookimpl in self._get_hookimpls():
            r = self._invoke(hookimpl, methods)
            if r is not None:
                results.append(r)
        # replay historic calls (used for pytest_plugin_registered etc.)
        for hist_kwargs, hist_extra in list(self._historic):
            hist = dict(hist_kwargs)
            if hist_extra is not None:
                hist.update(hist_extra)
            for hookimpl in self._get_hookimpls():
                self._invoke(hookimpl, hist)
        return results

    def _invoke(self, hookimpl, kwargs):
        args = []
        for pname in getattr(hookimpl.func, "_hook_args", None) or []:
            if pname not in kwargs:
                raise HookCallError(
                    "hook {} is missing argument {!r}".format(self.name, pname)
                )
            args.append(kwargs[pname])
        if hookimpl.wrapper:
            gen = hookimpl.func(*args)
            try:
                next(gen)
            except StopIteration:
                warnings.warn("hookwrapper did not yield: %r" % hookimpl)
                return None
            outcome = {"result": None, "exception": None}

            def _run():
                try:
                    outcome["result"] = self._call_after(hookimpl, kwargs)
                except BaseException as exc:  # noqa: BLE001
                    outcome["exception"] = exc
                try:
                    gen.send(outcome)
                except StopIteration:
                    pass

            # wrappers that `yield` (not `yield from`) drive the wrapped calls
            # themselves; call them here so their pre-yield code runs in order.
            try:
                return gen.close(), _run()  # pragma: no cover
            except Exception:
                return _run()
        return hookimpl.func(*args)

    def _get_hookimpls(self):
        return sorted(
            self.impls,
            key=lambda h: (not h.tryfirst, h.trylast),
        )


class HookRelay:
    def __init__(self):
        self._hooks = {}

    def __getattr__(self, name):
        try:
            return self._hooks[name]
        except KeyError:
            raise AttributeError(name)

    def set(self, name, hook):
        self._hooks[name] = hook


