"""Minimal stand-in for `iniconfig`: INI reader used by pytest's ini handling."""
import os
import re
from collections import OrderedDict

__version__ = "1.1.1"


class IniConfigError(Exception):
    pass


def _parse(lines):
    sections = OrderedDict()
    current = None
    for lineno, raw in enumerate(lines, 1):
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            current = line[1:-1].strip()
            sections.setdefault(current, OrderedDict())
            continue
        if current is None:
            raise IniConfigError("no section header at line %d" % lineno)
        if "=" in line:
            key, _, value = line.partition("=")
        elif ":" in line:
            key, _, value = line.partition(":")
        else:
            raise IniConfigError("bad line %d: %r" % (lineno, raw))
        sections[current][key.strip()] = value.strip()
    return sections


class SectionWrapper:
    def __init__(self, data):
        self._data = data

    def __getitem__(self, key):
        try:
            return self._data[key]
        except KeyError:
            raise KeyError(key)

    def __iter__(self):
        return iter(self._data)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def __contains__(self, key):
        return key in self._data


class IniConfig:
    def __init__(self, data, sections=None):
        self._data = data

    def __getitem__(self, name):
        try:
            return SectionWrapper(self._data[name])
        except KeyError:
            raise KeyError(name)

    def __contains__(self, name):
        return name in self._data

    def keys(self):
        return list(self._data)

    def sections(self):
        return list(self._data)

    def lineof(self, name):
        return 1


def _read(path):
    with open(path, encoding="utf-8") as f:
        return f.readlines()


def parse(path):
    return IniConfig(_parse(_read(path)))


def _read_string(s):
    return s.splitlines(keepends=True)


def _parse_string(s):
    return IniConfig(_parse(_read_string(s)))

