# ModelBase.__new__ must forward __classcell__ to type.__new__ (py3.6+ requirement).
def _patch_modelbase():
    try:
        from django.db.models.base import ModelBase
    except Exception:
        return
    _orig = ModelBase.__new__

    def __new__(cls, name, bases, attrs):
        parents = [b for b in bases if isinstance(b, ModelBase)]
        if parents and '__classcell__' in attrs:
            cell = attrs.pop('__classcell__')
        else:
            cell = None
        new_class = _orig(cls, name, bases, attrs)
