"""Make Django 1.11's vendored six importable on Python 3.12+ (find_module removed).

Sitecustomize shim: prepend to site-packages so `import six` works.
Only used to run the local test suite; not part of the fix.
"""
import sys
import importlib.abc
import importlib.machinery

import six as _six

for _i, _imp in enumerate(list(sys.meta_path)):
    if type(_imp).__name__ == '_SixMetaPathImporter' and getattr(_imp, 'name', '') == 'six':
        sys.meta_path.remove(_imp)
        _shim = _imp
        break
else:
    raise RuntimeError('six _SixMetaPathImporter not found in sys.meta_path')


class _Importer(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def __init__(self):
        self.name = _shim.name
        self.known_modules = _shim.known_modules
        self._shim = _shim

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in self.known_modules:
            return None
        return importlib.machinery.ModuleSpec(fullname, self, is_package=self._shim.is_package(fullname))

    def create_module(self, spec):
        return self._shim.load_module(spec.name)

    def exec_module(self, module):
        pass

    # legacy API replacement for code that calls find_module/load_module directly
    def find_module(self, fullname, path=None):
        if fullname in self.known_modules:
            return self
        return None

    def load_module(self, fullname):
        return self._shim.load_module(fullname)


sys.meta_path.insert(0, _Importer())

"""Minimal `cgi` module for Python 3.13, enough for Django 1.11's multipartparser.

Django 1.11 imports cgi.parse_header, cgi.valid_boundary, cgi.ValidBoundary,
cgi.FieldStorage-ish names. Provide them.
"""
import email.parser
import re

__all__ = ['parse_header', 'valid_boundary', 'ValidBoundary', 'escape']

ValidBoundary = re.compile(r'^[ -~]{0,200}[!-~]$')


def parse_header(line):
    """Parse a Content-type like header; return (main value, params dict)."""
    if not line:
        return line, {}
    parts = email.parser.HeaderParser().parsestr('Content-Type: ' + line)
    key = parts.get_content_type()
    pdict = {}
    for k, v in parts.get_params()[1:]:
        pdict[k] = v
    if 'boundary' in pdict:
        pdict['boundary'] = pdict['boundary'].encode('ascii')
    return key, pdict


def valid_boundary(s):
    if isinstance(s, bytes):
        try:
            s = s.decode('latin-1')
        except UnicodeDecodeError:
            return False
    return bool(ValidBoundary.match(s))


def escape(s, quote=False):
    """Obsolete html escaping helper kept for compatibility."""
    import html
    return html.escape(s, quote)

