"""SHIM (not part of the fix).

Python 3.13's import bootstrap unconditionally sets ``module.__file__ =
spec.origin`` (None for namespace packages), so ``hasattr(module, '__file__')``
is True for namespace packages. Django 1.11's migration loader relies on that
check to detect empty/namespace migrations directories.

Wrap ``_init_module_attrs`` so the ``__file__`` assignment only happens when the
spec actually refers to a file location (has_location), which is the pre-3.13
behaviour the Django code expects.
"""
import importlib._bootstrap as _bootstrap

_bootstrap_external = None
try:
    import importlib._bootstrap_external as _bootstrap_external
except ImportError:  # pragma: no cover
    pass


class _SpecProxy(object):
    """Delegates to the real spec but hides a location-less origin."""

    def __init__(self, spec):
        self._spec = spec

    def __getattr__(self, name):
        return getattr(self._spec, name)

    @property
    def origin(self):
        if not self._spec.has_location:
            return None
        return self._spec.origin


_ORIG = _bootstrap._init_module_attrs


def _init_module_attrs(spec, module=None, *, override=False):
    return _ORIG(_SpecProxy(spec), module, override=override)


_bootstrap._init_module_attrs = _init_module_attrs

