"""SHIM (not part of the fix).

CPython 3.13's import bootstrap deliberately sets ``module.__file__ = None`` for
namespace packages (importlib/_bootstrap.py, "this is the best place to ensure
this consistency", bpo-32305). Django 1.11's migration loader detects
empty/namespace migrations directories with ``hasattr(module, '__file__')``,
which Python 3.6-3.11 satisfied because the attribute simply was not present.

Recreate the old behaviour: strip a ``__file__`` that is None so hasattr() is
False again. Only used to run the Django test suite on this interpreter.
"""
import importlib._bootstrap as _bootstrap

_bootstrap_external = None
try:
    import importlib._bootstrap_external as _bootstrap_external
except ImportError:  # pragma: no cover
    pass


class _ModuleProxy(object):
    """Delegates to the real module but drops a None __file__."""

    def __init__(self, module):
        object.__setattr__(self, '_module', module)

    def __getattr__(self, name):
        return getattr(self._module, name)

    def __setattr__(self, name, value):
        if name == '__file__' and value is None:
            # Mimic pre-3.13: no __file__ attribute at all.
            self.__dict__.pop('__file__', None)
            return
        setattr(self._module, name, value)

    @property
    def __dict__(self):
        return self._module.__dict__

    @property
    def __class__(self):
        return self._module.__class__


_ORIG = _bootstrap._init_module_attrs


def _init_module_attrs(spec, module, *, override=False):
    return _ORIG(spec, _ModuleProxy(module), override=override)


_bootstrap._init_module_attrs = _init_module_attrs

