def _patch_metaclass_classcell():
    """Restore __classcell__ propagation for ModelBase.__new__.

    Python 3.13 rejects class bodies whose `__class__` cell was not filled by
    type.__new__; ModelBase builds a fresh attrs dict, so the cell never gets
    set. Fill the cell once the class exists.
    """
    try:
        import django.db.models.base as _base
    except Exception:
        return
    orig_new = _base.ModelBase.__new__

    def __new__(cls, name, bases, attrs):
        cell = attrs.get('__classcell__')
        new_class = orig_new(cls, name, bases, attrs)
        if cell is not None:
            try:
                cell.cell_contents
            except ValueError:
                cell.cell_contents = new_class
        return new_class

    _base.ModelBase.__new__ = __new__


